pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: owner approves logger address(0x1), then owner tries to revoke it
        address owner = address(this);
        address logger = address(0x1);

        // Owner approves logger
        vm.prank(owner);
        c.setApprovedLogger(logger, true);

        // Owner then tries to revoke approval
        vm.prank(owner);
        c.setApprovedLogger(logger, false);

        // Check if logger is still approved - should be false (revoked)
        bool isApproved = c.approvedToLog(logger);

        // On the reference contract, the revocation succeeded, so isApproved == false
        // On the buggy contract, the owner's call reverts (msg.sender != _contractOwner fails),
        // so the logger remains approved: isApproved == true
        assertTrue(!isApproved, "Logger should not be approved after owner revokes");
    }
}

