pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a caller that is NOT approved
        address caller = address(0x1234);
        vm.prank(caller);
        bool result = c.logRedemptionRequested(address(0), bytes32(0), 0, "", 0, "");
        // In reference (P): approvedToLog returns false, so logRedemptionRequested returns true (statement: if (!approvedToLog(msg.sender)) return false; -> false, continues)
        // In mutant (M): approvedToLog returns false, but condition is inverted: if (approvedToLog(msg.sender)) return false; -> false, so continues and returns true — WAIT, actually mutant returns true as well? Let's re-read.
        // Mutant: if (approvedToLog(msg.sender)) return false; else emit and return true. Since approvedToLog is false, it does NOT early return; it emits and returns true.
        // But the stated difference: "Invert the condition checking approvedToLog to return true when not approved." That means: original returns false when not approved; mutant returns true when not approved.
        // Original: if (!approvedToLog(msg.sender)) return false; -> if approved is false, it returns false. Mutant: if (approvedToLog(msg.sender)) return false; -> if approved is true, returns false; if approved false, does not return false, then emits and returns true.
        // So for a non-approved caller, original returns false, mutant returns true.
        assertTrue(result, "non-approved caller should get false in reference, but mutant returns true");
    }
}

